function thankYouPage($s):string{
 sessionStart();$r=$_SESSION['bookingReceipt']??null;
 if(!$r||($r['expires']??0)<time())return '<main id="main" class="container thank-page"><div class="thank-empty"><p class="kicker">YOUR NEXT DUBAI ADVENTURE</p><h1>Let’s make it memorable.</h1><p>Send a booking request to see your reference and next steps here.</p><a class="button" href="/attractions">Explore experiences</a></div></main>';
 $wa='https://wa.me/'.preg_replace('/\D/','',$s['whatsapp']).'?text='.rawurlencode('Hello '.$s['name'].', I would like to discuss booking request '.$r['reference'].' for '.$r['title'].'.');
 $date=DateTime::createFromFormat('!Y-m-d',$r['travelDate']);
 return '<main id="main" class="container thank-page"><section class="thank-layout" aria-labelledby="thank-title"><div class="thank-copy"><span class="thank-check" aria-hidden="true"><svg viewBox="0 0 48 48" fill="none"><path d="m13 24 8 8 15-16" stroke="currentColor" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg></span><p class="kicker">REQUEST SUCCESSFULLY RECEIVED</p><h1 id="thank-title">Thank you!<br><span>Your adventure awaits.</span></h1><p class="thank-lead">We’ve received your booking request. Our team will contact you to confirm availability, the final price and your experience details.</p><div class="thank-summary"><div class="thank-reference"><span>YOUR BOOKING REFERENCE</span><strong>'.e($r['reference']).'</strong></div><dl><div><dt>Experience</dt><dd>'.e($r['title']).'</dd></div><div><dt>Package</dt><dd>'.e($r['packageName']).'</dd></div><div><dt>Preferred date</dt><dd>'.e($date?$date->format('j F Y'):$r['travelDate']).'</dd></div><div><dt>Status</dt><dd><span class="thank-status">Pending confirmation</span></dd></div></dl></div><div class="thank-actions"><a class="button" href="'.e($wa).'" target="_blank" rel="noopener noreferrer">Discuss on WhatsApp <span aria-hidden="true">↗</span></a><a class="thank-browse" href="/attractions">Explore more experiences <span aria-hidden="true">→</span></a></div><p class="thank-note">Keep your reference handy when speaking with our team. Your booking is confirmed once we contact you with the final details.</p></div><aside class="thank-next"><p class="kicker">FROM REQUEST TO ADVENTURE</p><h2>What happens next?</h2><ol><li><span>01</span><div><h3>We review your request</h3><p>We check your selected experience, date and package availability.</p></div></li><li><span>02</span><div><h3>We get in touch</h3><p>Our team will contact you using the details you provided to arrange the next steps.</p></div></li><li><span>03</span><div><h3>You’re ready to explore</h3><p>Once confirmed, we’ll share the details you need for a memorable day.</p></div></li></ol><div class="thank-help"><span>Need a hand?</span><a href="tel:'.e(preg_replace('/[^+\d]/','',$s['phone'])).'">'.e($s['phone']).'</a><p>We’re here to help plan your Dubai experience.</p></div><svg class="thank-dunes" viewBox="0 0 480 100" aria-hidden="true"><path d="M0 80Q100-35 245 55T480 25V100H0Z" fill="#ff9c58" opacity=".3"/><path d="M0 95Q160 5 300 75T480 50V100H0Z" fill="#ff9c58" opacity=".6"/></svg></aside></section></main>';
